-- ============================================================
-- Better Auth tables (replaces Supabase Auth as identity store)
--
-- Schema generated by @better-auth/cli for better-auth 1.6.23 with the
-- passkey + admin plugins, adapted: text ids -> uuid (auth.ts generateId
-- returns crypto.randomUUID(), so RLS auth.uid() and profile FKs keep
-- working). Better Auth reaches these tables over a direct postgres
-- connection (DATABASE_URL); PostgREST roles are locked out below.
-- ============================================================

create table "user" (
  "id" uuid not null primary key,
  "name" text not null,
  "email" text not null unique,
  "emailVerified" boolean not null,
  "image" text,
  "createdAt" timestamptz default current_timestamp not null,
  "updatedAt" timestamptz default current_timestamp not null,
  -- admin plugin
  "role" text,
  "banned" boolean,
  "banReason" text,
  "banExpires" timestamptz
);

create table "session" (
  "id" uuid not null primary key,
  "expiresAt" timestamptz not null,
  "token" text not null unique,
  "createdAt" timestamptz default current_timestamp not null,
  "updatedAt" timestamptz not null,
  "ipAddress" text,
  "userAgent" text,
  "userId" uuid not null references "user" ("id") on delete cascade,
  -- admin plugin
  "impersonatedBy" uuid
);

create table "account" (
  "id" uuid not null primary key,
  "accountId" text not null,
  "providerId" text not null,
  "userId" uuid not null references "user" ("id") on delete cascade,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text,
  "createdAt" timestamptz default current_timestamp not null,
  "updatedAt" timestamptz not null
);

create table "verification" (
  "id" uuid not null primary key,
  "identifier" text not null,
  "value" text not null,
  "expiresAt" timestamptz not null,
  "createdAt" timestamptz default current_timestamp not null,
  "updatedAt" timestamptz default current_timestamp not null
);

create table "passkey" (
  "id" uuid not null primary key,
  "name" text,
  "publicKey" text not null,
  "userId" uuid not null references "user" ("id") on delete cascade,
  "credentialID" text not null,
  "counter" integer not null,
  "deviceType" text not null,
  "backedUp" boolean not null,
  "transports" text,
  "createdAt" timestamptz,
  "aaguid" text
);

create index "session_userId_idx" on "session" ("userId");
create index "account_userId_idx" on "account" ("userId");
create index "verification_identifier_idx" on "verification" ("identifier");
create index "passkey_userId_idx" on "passkey" ("userId");
create index "passkey_credentialID_idx" on "passkey" ("credentialID");

-- Lock the identity tables away from PostgREST: RLS with no policies plus
-- revoked grants. The direct postgres connection is unaffected.
alter table "user"         enable row level security;
alter table "session"      enable row level security;
alter table "account"      enable row level security;
alter table "verification" enable row level security;
alter table "passkey"      enable row level security;

revoke all on "user", "session", "account", "verification", "passkey"
  from anon, authenticated, service_role;

-- ------------------------------------------------------------
-- Add foreign key constraint to profiles now that user table exists.
-- Re-point profiles at the new identity table (fresh start on
-- users: existing auth.users accounts are abandoned, admin
-- recreates users via the settings UI / create-admin script).
-- auth.users itself stays — it is supabase-managed and unused.
-- ------------------------------------------------------------
delete from profiles;

alter table profiles
  add constraint profiles_id_fkey
  foreign key (id) references "user" ("id") on delete cascade;
